const raw = $json.output;

if (!raw) {
  throw new Error('AI Interview returned no output');
}

let data;

try {
  data = JSON.parse(
    String(raw)
      .replace(/^```json\s*/i, '')
      .replace(/\s*```$/i, '')
      .trim()
  );
} catch (e) {
  throw new Error('Invalid interview JSON: ' + e.message);
}

if (!['continue', 'completed'].includes(data.status)) {
  throw new Error('Invalid interview status');
}

if (typeof data.message !== 'string') {
  throw new Error('Interview message missing');
}

return [{
  json: {
    type: 'interview',
    status: data.status,
    message: data.message,
    process_json: data.process_json ?? null,
    screenshot_request: data.screenshot_request === true,
    session_id: $json.session_id ?? null
  }
}];

const item = $input.first();
const data = { ...item.json };

if (data.screenshot) {
  const base64 = String(data.screenshot).replace(/^data:image\/[^;]+;base64,/, '');

  const mime = data.screenshot_type || 'image/png';
  const extension = mime.split('/')[1] || 'png';

  item.binary = {
    screenshot: {
      data: base64,
      mimeType: mime,
      fileName: `screenshot.${extension}`,
      fileExtension: extension,
    }
  };
}

delete data.screenshot;
delete data.screenshot_type;

return [{
  json: data,
  binary: item.binary
}];

const body = $json.body ?? $json;
const question = String(body.question ?? '').trim();
if (!question) throw new Error('question is required');
const context = Array.isArray(body.context) ? body.context : [];
return [{ json: { question, context, user: body.user ?? null } }];

const raw = $json.output;
if (!raw) throw new Error('AI Question Agent returned no output');
let data;
try {
  data = JSON.parse(String(raw).replace(/^```json\s*/i, '').replace(/\s*```$/i, '').trim());
} catch (e) {
  throw new Error('Invalid question JSON: ' + e.message);
}
const allowed = ['answered', 'insufficient', 'conflict'];
if (!allowed.includes(data.status)) throw new Error('Invalid question status');
if (typeof data.answer !== 'string' || !data.answer.trim()) throw new Error('Question answer missing');
const sources = Array.isArray(data.sources)
  ? data.sources
      .filter((s) => s && typeof s === 'object' && typeof s.name === 'string' && s.name.trim())
      .map((s) => ({
        name: s.name,
        url: typeof s.url === 'string' ? s.url : '',
        fragment: typeof s.fragment === 'string' ? s.fragment : ''
      }))
      .slice(0, 5)
  : [];
return [{ json: { type: 'question', status: data.status, answer: data.answer.trim(), sources } }];
